# Subconverter CI 远程部署脚本 (PowerShell) # 前置条件：安装 Git CLI (winget install --id Git.Git) param( [string]$Repo = "whua898/subconverter", [string]$SshHost = "user@vps-ip", [string]$RemoteComposeDir = "/opt/subconverter", [int]$PollInterval = 30, [int]$MaxTimeout = 900 ) function Log-Info { param([string]$Msg) Write-Host "[INFO] $(Get-Date -Format 'HH:mm:ss') $Msg" } function Log-Success { param([string]$Msg) Write-Host "[OK] $(Get-Date -Format 'HH:mm:ss') $Msg" -ForegroundColor Green } function Log-Error { param([string]$Msg) Write-Host "[ERROR] $(Get-Date -Format 'HH:mm:ss') $Msg" -ForegroundColor Red } function Invoke-Retrying { param( [scriptblock]$Script, [int]$MaxAttempts = 3, [int]$DelaySeconds = 2 ) $attempt = 1 while ($attempt -le $MaxAttempts) { try { return & $Script } catch { if ($attempt -ge $MaxAttempts) { throw } Start-Sleep -Seconds $DelaySeconds $attempt++ } } } function Invoke-GitPush { Log-Info "[1/6] Git 提交并推送..." $commitMsg = "fix: 自动修复 $(Get-Date -Format 'yyyyMMdd-HHmmss')" if (git diff --quiet) { Log-Info "无新变更，跳过 commit" } else { git add . git commit -m $commitMsg | Out-Null } git push --set-upstream origin HEAD:main 2>&1 | Out-Null Log-Success "推送完成: $commitMsg" } function Wait-GithubActions { param([string]$Repo, [int]$MaxTimeout) Log-Info "[2/6] 等待 GitHub Actions 启动..." Start-Sleep -Seconds 10 $startTime = Get-Date Log-Info "[3/6] 轮询编译状态（每 ${PollInterval}s）..." while ($true) { $elapsed = (Get-Date) - $startTime if ($elapsed.TotalSeconds -gt $MaxTimeout) { Log-Error "编译超时（${MaxTimeout}s），退出" exit 1 } $list = gh run list --repo $Repo --limit 1 --json databaseId,status,conclusion --jq '.[0]' 2>$null if (-not $list) { Log-Error "无法获取 run list" Start-Sleep -Seconds $PollInterval continue } $runId = $list.databaseId $status = $list.status $conclusion = $list.conclusion Log-Info "Run #$runId 状态: $status | 结论: $conclusion" if ($status -eq "completed") { if ($conclusion -eq "success") { Log-Success "编译成功！" return } else { Log-Error "编译失败: $conclusion" gh run view $runId --repo $Repo --log-failed 2>&1 | Out-Null throw "GitHub Actions 失败" } } Start-Sleep -Seconds $PollInterval } } function Invoke-SshDeploy { param( [string]$Host, [string]$Dir ) Log-Info "[4/6] SSH 远程更新容器..." $sshCmd = "cd $Dir && docker compose pull && docker compose up -d --force-recreate" Invoke-Retrying -Script { ssh $Host $sshCmd } -MaxAttempts 3 -DelaySeconds 5 Log-Success "远程更新完成" } function Invoke-HealthCheck { param([string]$Host) Log-Info "[5/6] 验证服务状态..." Start-Sleep -Seconds 5 try { $r = Invoke-WebRequest -Uri "http://${Host}:8080/" -UseBasicParsing -TimeoutSec 10 $code = $r.StatusCode } catch { $code = "000" } if ($code -eq 200) { Log-Success "服务健康检查通过 (HTTP $code)" } else { Log-Error "服务异常 (HTTP $code)" throw "健康检查失败" } } function Invoke-SubscriptionCheck { param([string]$Url, [string]$Target = "v2ray") Log-Info "[6/6] 订阅转换验证..." try { $r = Invoke-WebRequest -Uri $Url -UseBasicParsing -TimeoutSec 15 $body = $r.Content } catch { throw "订阅请求失败: $_" } if (-not $body -or $body.Length -lt 10) { throw "返回内容为空或过短" } try { $bytes = [System.Convert]::FromBase64String($body) $text = [System.Text.Encoding]::UTF8.GetString($bytes) } catch { throw "Base64 解码失败" } if ($text -notmatch "vmess://|vless://|trojan://|ss://|ssr://|hysteria2://|tuic://") { throw "未检测到已知协议节点" } Log-Success "订阅验证通过" Log-Info "解码长度: $($text.Length) 字符" } try { $ErrorActionPreference = "Stop" Invoke-GitPush -Repo $Repo Wait-GithubActions -Repo $Repo -MaxTimeout $MaxTimeout Invoke-SshDeploy -Host $SshHost -Dir $RemoteComposeDir Invoke-HealthCheck -Host $SshHost $subUrl = "http://${SshHost}:25500/sub?target=${Target}&url=https://raw.githubusercontent.com/xxx/xxx.txt" Invoke-SubscriptionCheck -Url $subUrl Log-Success "=== 全流程完成 ===" } catch { Log-Error $_ exit 1 }